      "media": [
        {
          "type": "image",
          "url": "https://the-brandidentity.com/uploads/articles/2026/10/why-maniac-studio-put-a-cat-at-the-centre-of-the-pagodas-identity/The-Pagoda-Maniac-Studio-01.jpg"
        }
      ],
      "hasCaseStudy": true,
